/* R1369 — member preview trust, accessibility and detail-check refinement */
(()=>{'use strict';
const API='https://franklin-navigator-membership.onrender.com',q=(s,r=document)=>r.querySelector(s);let urls=[],timer=0,lastProfile='';
const isEs=()=>window.FranklinI18n?.language==='es'||localStorage.getItem('franklinLanguage')==='es';
const T=(en,es)=>isEs()?es:en;
function clearUrls(){for(const u of urls)URL.revokeObjectURL(u);urls=[]}
function announce(text){let n=q('[data-r1369-announcer]');if(!n){n=document.createElement('div');n.className='r1369-sr-status';n.setAttribute('role','status');n.setAttribute('aria-live','polite');n.dataset.r1369Announcer='';document.body.append(n)}n.textContent='';setTimeout(()=>{n.textContent=text},10)}
async function req(path,opts={}){const r=await fetch(API+path,{credentials:'include',cache:'no-store',...opts,headers:opts.body?{'Content-Type':'application/json',...(opts.headers||{})}:opts.headers});let out={};try{out=await r.json()}catch{}if(!r.ok)throw new Error(out?.error?.message||out?.message||T('We could not complete that request.','No pudimos completar esa solicitud.'));return out}
const label=k=>({COUPON:T('Coupon','Cupón'),SPECIAL:T('Special offer','Oferta especial'),SALE:T('Sale','Venta'),PROMOTION:T('Promotion','Promoción'),EVENT:T('Event','Evento')}[k]||T('Offer or event','Oferta o evento'));
const mediaLabel=k=>({COUPON_GRAPHIC:T('Coupon graphic','Gráfico de cupón'),SALE_GRAPHIC:T('Sale graphic','Gráfico de venta'),PROMOTIONAL_GRAPHIC:T('Promotional graphic','Gráfico promocional'),PROMOTIONAL_FLYER:T('Promotional flyer','Volante promocional'),EVENT_FLYER:T('Event flyer','Volante de evento')}[k]||T('Promotional media','Contenido promocional'));
const stateLabel=s=>({DRAFT:T('Draft','Borrador'),SUBMITTED:T('Submitted for review','Enviado para revisión'),PENDING_REVIEW:T('Pending review','Pendiente de revisión'),IN_REVIEW:T('In review','En revisión'),APPROVED:T('Approved','Aprobado'),PUBLISHED:T('Published','Publicado'),EXPIRED:T('Expired','Vencido'),REJECTED:T('Needs changes','Necesita cambios'),REMOVED:T('Removed','Eliminado')}[String(s||'').toUpperCase()]||T('Status unavailable','Estado no disponible'));
function safePublicUrl(value){if(!value)return null;try{const u=new URL(value,location.origin);return u.protocol==='https:'||u.protocol==='http:'?u:null}catch{return null}}
function line(box,strong,value){if(!value)return;const p=document.createElement('p'),b=document.createElement('strong');b.textContent=strong;p.append(b,document.createTextNode(String(value)));box.append(p)}
function button(text,fn,primary=false){const b=document.createElement('button');b.type='button';b.className='button'+(primary?' primary':'');b.textContent=text;b.addEventListener('click',fn);return b}
function detailCheck(item){const box=document.createElement('div');box.className='r1369-detail-check';const h=document.createElement('strong');h.textContent=T('Details check','Revisión de detalles');box.append(h);const missing=[];if(!item.end_at)missing.push(T('Add an end or expiration time when the offer or event is time-limited.','Agregue una fecha u hora de finalización o vencimiento cuando corresponda.'));if(!item.action_url)missing.push(T('Add a public action link when residents need a next step.','Agregue un enlace público de acción cuando los residentes necesiten un próximo paso.'));if(item.kind==='EVENT'&&!item.event_location)missing.push(T('Add a location or clearly explain where the event happens.','Agregue una ubicación o explique claramente dónde se realiza el evento.'));if(item.kind==='EVENT'&&!item.start_at)missing.push(T('Add a start date and time for the event.','Agregue una fecha y hora de inicio para el evento.'));if(!missing.length){const p=document.createElement('p');p.textContent=T('The main resident-facing details are present. Franklin review still applies before publication.','Los principales detalles visibles para residentes están presentes. La revisión de Franklin aún se aplica antes de la publicación.');box.append(p)}else{const p=document.createElement('p');p.textContent=T('Consider adding the following before submitting or publishing:','Considere agregar lo siguiente antes de enviar o publicar:');const ul=document.createElement('ul');missing.forEach(x=>{const li=document.createElement('li');li.textContent=x;ul.append(li)});box.append(p,ul)}return box}
function itemPreview(item,media){const card=document.createElement('article');card.className='r1369-preview-card';const eye=document.createElement('div');eye.className='eyebrow';eye.textContent=T('Resident preview','Vista previa para residentes');const h=document.createElement('h3');h.textContent=item.title||T('Untitled draft','Borrador sin título');const d=document.createElement('p');d.textContent=item.description||T('No description added yet.','Aún no se agregó una descripción.');const chip=document.createElement('span');chip.className='r1369-status-chip';chip.textContent=stateLabel(item.state);chip.setAttribute('aria-label',T('Review status: ','Estado de revisión: ')+stateLabel(item.state));card.append(eye,h,chip,d);line(card,T('Type: ','Tipo: '),label(item.kind));line(card,T('Code: ','Código: '),item.promo_code);line(card,T('Offer: ','Oferta: '),item.discount_text);line(card,T('Starts: ','Comienza: '),item.start_at?new Date(item.start_at).toLocaleString():'');line(card,T('Ends: ','Termina: '),item.end_at?new Date(item.end_at).toLocaleString():'');line(card,T('Location: ','Ubicación: '),item.event_location);const action=safePublicUrl(item.action_url);if(action){const a=document.createElement('a');a.href=action.href;a.target='_blank';a.rel='noopener noreferrer nofollow';a.textContent=T('Open public action link','Abrir enlace público de acción');card.append(a)}else if(item.action_url){const p=document.createElement('p');p.className='fine-print';p.textContent=T('This action link is hidden because it is not a safe http/https address.','Este enlace de acción está oculto porque no es una dirección http/https segura.');card.append(p)}card.append(detailCheck(item));const m=media.filter(x=>x.promotion_id===item.promotion_id);const note=document.createElement('p');note.className='fine-print';note.textContent=m.length?T(`${m.length} attached media item${m.length===1?'':'s'}. Preview or manage it below.`,`${m.length} elemento${m.length===1?'':'s'} multimedia adjunto${m.length===1?'':'s'}. Previsualícelo o adminístrelo abajo.`):T('No promotional media attached yet.','Aún no hay contenido promocional adjunto.');card.append(note);return card}
async function previewMedia(m,row,btn){const old=q('[data-r1369-media-preview]',row);if(old){old.remove();btn?.setAttribute('aria-expanded','false');announce(T('Media preview closed.','Vista previa cerrada.'));return}btn?.setAttribute('aria-busy','true');try{const r=await fetch(API+m.previewUrl,{credentials:'include',cache:'no-store'});if(!r.ok)throw new Error(T('This media preview is not available right now.','Esta vista previa no está disponible en este momento.'));const blob=await r.blob(),u=URL.createObjectURL(blob);urls.push(u);const box=document.createElement('div');box.className='r1369-media-preview';box.dataset.r1369MediaPreview='';box.tabIndex=-1;if((m.mime_type||'').toLowerCase()==='application/pdf'){const a=document.createElement('a');a.href=u;a.target='_blank';a.rel='noopener noreferrer';a.className='button';a.textContent=T('Open PDF preview','Abrir vista previa del PDF');box.append(a)}else if((m.mime_type||'').toLowerCase().startsWith('image/')){const img=document.createElement('img');img.src=u;img.alt=T('Preview of your promotional media','Vista previa de su contenido promocional');img.loading='lazy';box.append(img)}else{throw new Error(T('This media type cannot be previewed here.','Este tipo de contenido no se puede previsualizar aquí.'))}row.append(box);btn?.setAttribute('aria-expanded','true');box.focus();announce(T('Media preview opened.','Vista previa abierta.'))}finally{btn?.removeAttribute('aria-busy')}}
async function removeMedia(m,btn){if(!confirm(T('Remove this promotional media?','¿Eliminar este contenido promocional?')))return;btn?.setAttribute('aria-busy','true');btn&&(btn.disabled=true);try{const profile=currentProfile();await req('/api/member/promotions/media/remove?profileId='+encodeURIComponent(profile),{method:'POST',body:JSON.stringify({mediaId:m.media_id})});announce(T('Promotional media removed.','Contenido promocional eliminado.'));await refresh(true)}finally{if(btn){btn.disabled=false;btn.removeAttribute('aria-busy')}}}
function replaceMedia(m){const f=q('[data-r1365-media-form]');if(!f)return;f.elements.promotionId.value=m.promotion_id;f.elements.mediaKind.value=m.media_kind;f.scrollIntoView({behavior:'smooth',block:'start'});f.elements.file?.focus();announce(T('Media replacement form ready.','Formulario de reemplazo listo.'))}
function mediaRow(m,items){const row=document.createElement('article');row.className='r1369-media-row';const h=document.createElement('strong');h.textContent=mediaLabel(m.media_kind);const meta=document.createElement('p');meta.className='fine-print';const item=items.find(x=>x.promotion_id===m.promotion_id);meta.textContent=`${stateLabel(m.state)} · ${Math.round((m.byte_size||0)/1024)} KB${item?' · '+item.title:''}`;const actions=document.createElement('div');actions.className='r1365-actions';let previewBtn;previewBtn=button(T('Preview media','Vista previa del contenido'),()=>previewMedia(m,row,previewBtn).catch(showError));previewBtn.setAttribute('aria-expanded','false');actions.append(previewBtn);if(String(m.state||'').toUpperCase()!=='SUBMITTED'){let removeBtn;removeBtn=button(T('Remove media','Eliminar contenido'),()=>removeMedia(m,removeBtn).catch(showError));actions.append(removeBtn)}actions.append(button(T('Replace media','Reemplazar contenido'),()=>replaceMedia(m)));row.append(h,meta,actions);return row}
function currentProfile(){return q('[data-r1365-profile-picker] select')?.value||''}
function showError(e){const s=q('[data-r1365-status]');if(s){s.textContent=e.message;s.className='r1365-status warn'}announce(e.message)}
async function refresh(force=false){const root=q('[data-r1369-preview-workspace]'),profile=currentProfile();if(!root||!profile)return;if(!force&&profile===lastProfile&&root.dataset.loaded==='1')return;lastProfile=profile;root.dataset.loaded='0';root.hidden=false;root.setAttribute('aria-busy','true');root.textContent=T('Loading preview and media controls…','Cargando vista previa y controles multimedia…');try{const [a,b]=await Promise.all([req('/api/member/promotions/list?profileId='+encodeURIComponent(profile)),req('/api/member/promotions/media/list?profileId='+encodeURIComponent(profile))]);clearUrls();root.replaceChildren();const eye=document.createElement('div');eye.className='eyebrow';eye.textContent=T('Preview before publication','Vista previa antes de publicar');const h=document.createElement('h2');h.textContent=T('Review what residents will understand','Revise lo que entenderán los residentes');const intro=document.createElement('p');intro.textContent=T('Preview your offer or event details, check for missing resident-facing details, then preview, replace or remove attached promotional media. Franklin review still applies before publication.','Previsualice los detalles de su oferta o evento, revise si faltan datos visibles para residentes y luego previsualice, reemplace o elimine el contenido promocional adjunto. La revisión de Franklin aún se aplica antes de la publicación.');root.append(eye,h,intro);const items=a.promotions||[],media=b.media||[];if(!items.length){const p=document.createElement('p');p.textContent=T('Create a draft above to start a resident preview.','Cree un borrador arriba para iniciar una vista previa para residentes.');root.append(p)}else{const grid=document.createElement('div');grid.className='r1369-preview-grid';items.forEach(i=>grid.append(itemPreview(i,media)));root.append(grid)}const mh=document.createElement('h3');mh.textContent=T('Attached promotional media','Contenido promocional adjunto');root.append(mh);if(!media.length){const p=document.createElement('p');p.textContent=T('No promotional graphics, flyer images or PDF documents are attached yet.','Aún no hay gráficos promocionales, imágenes de volantes ni documentos PDF adjuntos.');root.append(p)}else{const list=document.createElement('div');list.className='r1369-media-grid';media.forEach(m=>list.append(mediaRow(m,items)));root.append(list)}root.dataset.loaded='1';announce(T('Preview and media controls loaded.','Vista previa y controles multimedia cargados.'))}catch(e){root.hidden=true;showError(e)}finally{root.removeAttribute('aria-busy')}}
function schedule(force=false){clearTimeout(timer);timer=setTimeout(()=>refresh(force),120)}
document.addEventListener('DOMContentLoaded',()=>{const status=q('[data-r1365-status]');if(status)new MutationObserver(()=>{if(/tools are ready|herramientas.*listas/i.test(status.textContent))schedule(true)}).observe(status,{childList:true,subtree:true,characterData:true});const wait=setInterval(()=>{const sel=q('[data-r1365-profile-picker] select');if(!sel)return;clearInterval(wait);sel.addEventListener('change',()=>schedule(true));schedule(true)},120);setTimeout(()=>clearInterval(wait),10000);document.querySelectorAll('[data-r37-lang]').forEach(b=>b.addEventListener('click',()=>setTimeout(()=>schedule(true),0)))})
})();
